//! `export_contracts` — regenerate the committed web/TUI TypeScript contracts
//! from their ts-rs Rust source of truth in `jeryu-readmodel::contracts`.
//!
//! This binary is the genuine generator behind `contracts/generated/*.ts`:
//! the files carry the ts-rs "generated by" header because they are literally
//! ts-rs output written here. The drift test (`tests/contract_drift.rs`)
//! re-runs the same export into a clean temp dir and asserts byte-identity.
//!
//! Destination resolution (first match wins):
//!   1. `$TS_RS_EXPORT_DIR` if set (used by the drift test / CI).
//!   2. `<repo-root>/contracts/generated`, derived from `CARGO_MANIFEST_DIR`.

use std::path::PathBuf;

use jeryu_readmodel::contracts::{CONTRACT_COUNT, export_all_contracts};
use ts_rs::Config;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out_dir = match std::env::var_os("TS_RS_EXPORT_DIR") {
        Some(dir) => PathBuf::from(dir),
        None => {
            // CARGO_MANIFEST_DIR = <repo-root>/crates/jeryu-readmodel
            let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
            manifest_dir
                .join("..")
                .join("..")
                .join("contracts")
                .join("generated")
        }
    };

    std::fs::create_dir_all(&out_dir)?;
    let cfg = Config::new().with_out_dir(&out_dir);
    export_all_contracts(&cfg)?;

    println!(
        "exported {CONTRACT_COUNT} web/TUI contracts to {}",
        out_dir.display()
    );
    Ok(())
}
